package com.gregtech.gregtech.registry;
import com.gregtech.gregtech.block.BarsRules;import com.gregtech.gregtech.block.misc.*;import net.minecraft.world.level.block.Block;import net.minecraft.world.level.block.SoundType;import net.minecraft.world.level.block.state.BlockBehaviour;import net.minecraft.world.level.material.MapColor;import net.minecraft.world.item.Item;import net.neoforged.neoforge.registries.DeferredHolder;
public final class GTBars {private GTBars(){}private static final java.util.Map<String,DeferredHolder<Block,BarsBlock>> ALL=new java.util.LinkedHashMap<>();public static java.util.Collection<DeferredHolder<Block,BarsBlock>> all(){return java.util.List.copyOf(ALL.values());}public static BarsBlock get(String id){return ALL.get(id).get();}public static void initialize(){for(var spec:BarsRules.SPECS){var b=GTBlocks.BLOCKS.register(spec.id(),()->new BarsBlock(spec.material(),spec.tint(),spec.harvest(),BlockBehaviour.Properties.of().mapColor(MapColor.METAL).strength(5,spec.resistance()).requiresCorrectToolForDrops().sound(SoundType.METAL).noOcclusion()));ALL.put(spec.id(),b);GTBlocks.BLOCK_ITEMS.register(spec.id(),()->new BarsBlockItem(b.get(),new Item.Properties()));}}}
